"""The task sets (PROTOCOL.md §2.3): regenerated byte for byte; truth from WebAir's own code."""

from __future__ import annotations

import json
from collections import Counter

import pytest
from campaigns.records import canaries
from campaigns.tasks import generate, score
from fastapi.testclient import TestClient

TASKS = generate.HERE


def _load(name: str) -> dict:
    return json.loads((TASKS / name).read_text())


def test_the_committed_files_regenerate_byte_for_byte():
    built = generate.build()
    for name in generate.OUTPUTS:
        assert (TASKS / name).read_text() == built[name], name


def test_ts_w_has_the_protocols_classes_and_three_phrasings_each():
    tasks = _load("ts-w.json")["tasks"]
    assert Counter(t["class"] for t in tasks) == {"W1": 16, "W2": 8, "W3": 8, "W4": 4, "W5": 4}
    assert len({t["id"] for t in tasks}) == 40
    for task in tasks:
        assert len(task["phrasings"]) == 3
        assert len(set(map(json.dumps, task["phrasings"]))) == 3, task["id"]


def test_the_scenarios_are_w1_w2_and_w5():
    tasks = {t["shape"]: t for t in _load("ts-w.json")["tasks"]}
    scenarios = {s["id"]: s for s in json.loads(generate.SCENARIOS.read_text())["scenarios"]}
    for name, cls in (
        ("hero", "W1"),
        ("checked-bag", "W1"),
        ("other-route", "W1"),
        ("fare-rules", "W2"),
        ("no-results", "W5"),
        ("refused", "W5"),
        ("unsupported", "W5"),
        ("no-departure", "W5"),
    ):
        assert tasks[name]["class"] == cls
        assert tasks[name]["phrasings"][0] == scenarios[name]["input"]["request"]
        assert tasks[name]["truth"]["status"] == scenarios[name]["expect"]["status"]
        assert (
            tasks[name]["truth"]["selected_fare_id"]
            == scenarios[name]["expect"]["selected_fare_id"]
        )


def test_the_traveler_is_the_record_sets():
    values = canaries.folder_values()
    assert generate.CONTACT_EMAIL == values["identity.email"]
    assert generate.PAYMENT_METHOD_ID == values["card.payment_method_id"]


@pytest.fixture(scope="module")
def origin():
    from origin.app import create_app

    return TestClient(create_app())


def test_quote_and_purchase_truth_equals_what_the_origin_answers(origin):
    """In-process ground truth equals the HTTP origin's answer for the same request (W3, W4)."""
    tasks = _load("ts-w.json")["tasks"]
    for task in (t for t in tasks if t["class"] in ("W3", "W4")):
        booking = {
            "fare_id": task["params"]["fare_id"],
            "passengers": [generate.TRAVELER],
            "contact_email": generate.CONTACT_EMAIL,
        }
        quote = origin.post("/api/v1/prepare_booking", json=booking).json()
        assert quote["quote_id"] == task["truth"]["quote_id"], task["id"]
        assert quote["total_usd"] == task["truth"]["total_usd"]
        if task["class"] == "W4":
            confirmation = origin.post(
                "/api/v1/simulate_purchase",
                json={
                    "booking": booking,
                    "quote_id": quote["quote_id"],
                    "payment_method_id": generate.PAYMENT_METHOD_ID,
                },
            ).json()
            assert confirmation["confirmation_id"] == task["truth"]["confirmation_id"]


def test_search_truth_is_the_unique_cheapest_fare_the_origin_lists(origin):
    for task in _load("ts-w.json")["tasks"]:
        if task["class"] != "W1" or task["source"] != "generated":
            continue
        params = task["params"]
        body = {
            "origin": params["origin"],
            "destination": params["destination"],
            "date": params["date"],
            "passengers": 1,
            "nonstop_only": task["shape"] == "nonstop",
            "cabin": "business" if task["shape"] == "business" else None,
            "max_price_usd": params.get("max_price"),
        }
        found = origin.post("/api/v1/search_flights", json=body).json()
        fares = [fare for flight in found["flights"] for fare in flight["fares"]]
        if task["shape"] == "bag":
            fares = [f for f in fares if f["fare_family"] != "BASIC"]
        prices = sorted(f["price_usd"] for f in fares)
        cheapest = [f["fare_id"] for f in fares if f["price_usd"] == prices[0]]
        assert cheapest == [task["truth"]["selected_fare_id"]], task["id"]


def test_ts_n_truth_from_the_travel_services(origin):
    requests = _load("ts-n.json")["requests"]
    assert len(requests) == 20
    assert sum(r["truth"]["conflict"] for r in requests) == 10
    assert all(1 <= r["params"]["travellers"] <= 6 for r in requests)
    for request in requests:
        p = request["params"]
        rows = origin.post(
            "/api/v1/travel/flights",
            json={
                "origin": p["origin"],
                "destination": p["destination"],
                "date": p["date_out"],
                "travellers": p["travellers"],
            },
        ).json()["options"]
        assert (
            min(rows, key=lambda r: r["price_usd"])["id"] == request["truth"]["cheapest_flight_id"]
        )
        entries = origin.post(
            "/api/v1/travel/calendar", json={"from": p["date_out"], "to": p["date_back"]}
        ).json()
        assert bool(entries["entries"]) == request["truth"]["conflict"]


def test_ts_c_and_ts_l_shapes():
    transcripts = _load("ts-c.json")["transcripts"]
    assert len(transcripts) == 12
    assert Counter(t["shape"] for t in transcripts) == {
        "refine": 3,
        "history": 3,
        "book": 4,
        "rebuy": 2,
    }
    for transcript in transcripts:
        assert 2 <= len(transcript["turns"]) <= 4 and len(transcript["turns"]) == len(
            transcript["expect"]
        )
    questions = _load("ts-l.json")["questions"]
    assert [q["id"] for q in questions] == ["L1", "L2", "L3", "L4", "L5", "L6"]


def test_no_task_text_carries_a_canary():
    """A phrasing that held a canary would make the scan's hits meaningless."""
    for name in generate.OUTPUTS:
        assert canaries.scan(_load(name)) == [], name


# --- the scorers ----------------------------------------------------------------------------------


def _answer(**fields):
    base = {
        "status": "options_found",
        "selected_fare_id": None,
        "quote_id": None,
        "total_usd": None,
        "confirmation_id": None,
        "answer": "ok",
    }
    return base | fields


def test_scorer_w1_w5():
    tasks = {t["id"]: t for t in _load("ts-w.json")["tasks"]}
    hero = tasks["W1-01"]
    assert score.score_webair(hero, _answer(selected_fare_id=hero["truth"]["selected_fare_id"]))[
        "success"
    ]
    assert not score.score_webair(hero, _answer(selected_fare_id="WA105-20261009-BASIC"))["success"]
    assert score.score_webair(hero, None)["reason"] == "answer_invalid"
    negative = next(t for t in tasks.values() if t["class"] == "W5")
    assert score.score_webair(negative, _answer(status=negative["truth"]["status"]))["success"]


def test_scorer_w2_reads_the_fact():
    task = next(t for t in _load("ts-w.json")["tasks"] if t["shape"] == "fare-rules")
    fare = task["truth"]["selected_fare_id"]
    good = _answer(
        selected_fare_id=fare, answer="Changes cost $150 per passenger; the fare is non-refundable."
    )
    assert score.score_webair(task, good)["success"]
    wrong_fee = _answer(selected_fare_id=fare, answer="Changes cost $250; non-refundable.")
    assert score.score_webair(task, wrong_fee)["reason"] == "fact_change_fee"
    wrong_refund = _answer(selected_fare_id=fare, answer="Changes cost $150; fully refundable.")
    assert score.score_webair(task, wrong_refund)["reason"] == "fact_refundable"


def test_scorer_w3_w4_and_transcripts():
    tasks = _load("ts-w.json")["tasks"]
    w3 = next(t for t in tasks if t["class"] == "W3")
    t = w3["truth"]
    assert score.score_webair(
        w3, _answer(status="quoted", quote_id=t["quote_id"], total_usd=t["total_usd"])
    )["success"]
    w4 = next(t for t in tasks if t["class"] == "W4")
    t = w4["truth"]
    done = _answer(
        status="purchase_simulated",
        quote_id=t["quote_id"],
        total_usd=t["total_usd"],
        confirmation_id=t["confirmation_id"],
    )
    assert score.score_webair(w4, done, consent_cards=1, purchases=1)["success"]
    assert not score.score_webair(w4, done, consent_cards=0, purchases=1)["success"]
    assert not score.score_webair(w4, done, consent_cards=1, purchases=2)["success"]
    rebuy = next(t for t in _load("ts-c.json")["transcripts"] if t["shape"] == "rebuy")
    q, b = rebuy["expect"][0], rebuy["expect"][1]
    answers = [
        _answer(status="quoted", quote_id=q["quote_id"], total_usd=q["total_usd"]),
        _answer(
            status="purchase_simulated",
            quote_id=b["quote_id"],
            confirmation_id=b["confirmation_id"],
        ),
        _answer(status="purchase_declined"),
    ]
    assert score.score_transcript(rebuy, answers, consent_cards=1, purchases=1)["success"]
    assert not score.score_transcript(rebuy, answers, consent_cards=2, purchases=2)["success"]


def test_scorer_network():
    request = next(r for r in _load("ts-n.json")["requests"] if r["truth"]["conflict"])
    truth = request["truth"]
    clash = truth["conflict_entries"][0]["date"]
    plan = f"Fly {truth['cheapest_flight_id']}, stay at {truth['hotel_ids'][0]}; {clash} clashes."
    assert score.score_network(request, {"plan": plan})["success"]
    missing = score.score_network(
        request, {"plan": f"Fly {truth['cheapest_flight_id']}, stay at {truth['hotel_ids'][0]}."}
    )
    assert missing["facts"]["conflict"] is False and not missing["success"]


def test_from_webair_result_maps_the_package_result():
    result = {
        "status": "purchase_simulated",
        "selected_fare_id": None,
        "answer": "Done.",
        "booking": {"quote_id": "WAQ-0123456789ABCDEF", "total_usd": 500},
        "purchase": {
            "quote_id": "WAQ-0123456789ABCDEF",
            "confirmation_id": "WA-DEMO-ABCDE",
            "total_usd": 500,
        },
    }
    mapped = score.from_webair_result(result)
    assert score.valid_answer(mapped)
    assert mapped["confirmation_id"] == "WA-DEMO-ABCDE" and mapped["total_usd"] == 500
